-- The id is generated by the service; user_id (X-User-Id) is checked on every turn;
-- last_message_at drives the retention job.
CREATE TABLE chat_conversation (
    id              UUID         PRIMARY KEY,
    user_id         VARCHAR(64)  NOT NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    last_message_at TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE INDEX idx_chat_conversation_last_message_at ON chat_conversation (last_message_at);

-- The full transcript, append-only: questions and final answers, no tool messages. The model
-- gets only the newest assistant.chat.memory-max-messages.
CREATE TABLE chat_message (
    id              BIGSERIAL    PRIMARY KEY,
    conversation_id UUID         NOT NULL REFERENCES chat_conversation (id) ON DELETE CASCADE,
    role            VARCHAR(10)  NOT NULL CHECK (role IN ('USER', 'ASSISTANT')),
    content         TEXT         NOT NULL,
    created_at      TIMESTAMPTZ  NOT NULL DEFAULT now()
);

-- "Newest N messages of a conversation", read on every turn.
CREATE INDEX idx_chat_message_conversation_id ON chat_message (conversation_id, id);
